const CACHE_NAME="omega-sunlight-v1",ASSETS_TO_CACHE=["./","./index.html","./style.css","./js/app.min.js","./js/api.min.js","./js/chart.min.js","./js/i18n.min.js","./js/storage.min.js","./favicon.ico","./manifest.json","./images/icon-192x192.png","./images/icon-512x512.png","./images/icon-maskable-192x192.png","./images/icon-maskable-512x512.png"];self.addEventListener("install",e=>{e.waitUntil(caches.open(CACHE_NAME).then(e=>e.addAll(ASSETS_TO_CACHE)))}),self.addEventListener("activate",e=>{e.waitUntil(caches.keys().then(e=>Promise.all(e.map(e=>{if(e!==CACHE_NAME)return caches.delete(e)}))))}),self.addEventListener("fetch",e=>{e.respondWith(caches.match(e.request).then(n=>n||fetch(e.request)))});